lemma koszulCoefficient_at_excess_before_second {d r e : ℕ}
    (hr : 1 ≤ r) (he : e < d) :
    koszulCoefficient d r (d + e) = (N d : ℤ) - r + residual d r e

lemma completeIntersectionCoefficient_two_ge_point {d p e : ℕ}
    (hd : 2 ≤ d) (hcount : p = N d - 2) :
    (p : ℤ) ≤ completeIntersectionCoefficient d 2 (d + e)

lemma completeIntersectionCoefficient_two_hit_degree {d p q : ℕ}
    (hd : 2 ≤ d) (hcount : p = N d - 2) (hq : 1 ≤ q)
    (hhit : completeIntersectionCoefficient d 2 (d + q) ≤ p) : d = 2

lemma koszulPrefixHit_none_of_one_generator {d p : ℕ}
    (hd : 1 ≤ d) (hr : N d - p = 1) (e : ℕ) :
    ¬ koszulPrefixHit d p e

theorem expectedSyzygyCoefficient_eq_expectedChoppedHilbertFunction {d p : ℕ}
    (hd : 1 ≤ d) (hmin : IsExpectedSyzygyDegree d p) (t : ℕ) :
    expectedSyzygyCoefficient d p t = (expectedChoppedHilbertFunction d p t : ℤ)

theorem expectedSyzygyConclusion_of_mainConclusion {d p : ℕ}
    {a : PointCoordinates K p} (hd : 1 ≤ d) (hmin : IsExpectedSyzygyDegree d p)
    (hmain : MainConclusion K a d) : ExpectedSyzygyConclusion a d

theorem koszulPositiveCutoff_isLeast {d p : ℕ}
    (hd : 2 ≤ d) (hlo : N (d - 1) < p) (hhi : p < N d)
    (hr : 3 ≤ N d - p) :
    IsLeast {e : ℕ | 1 ≤ e ∧ koszulCoefficient d (N d - p) (d + e) ≤ p}
      (cutoff d (N d - p))

theorem affinePresentation_plane_apply {p : ℕ}
    (φ : Poly K 2 →ₐ[K] (Fin p → K)) (f : Poly K 3) (i : Fin p) :
    φ (affineDehom f) i = eval (chartPoint K (affinePresentationCoordinates φ) i) f

theorem affineCofactorIdeal_le_selectedAffineEvaluation_ker {c : ℕ}
    (δ : Fin (c + 1) → ℕ) (α β : RootIndex δ → K) :
    affineCofactorIdeal δ α β ≤ RingHom.ker (selectedAffineEvaluation δ α β).toRingHom

